<script setup lang="ts">import { computed, onMounted, ref, watch } from "vue"; import { useRoute, useRouter } from "vue-router"; import type { CategoryItem, PublishedGameSummary } from "@arcade/shared"; import { getCategories, getCategoryGames } from "../services/api"; import { readFavorites, toggleFavorite, rememberRecent } from "../services/portalStorage"; import GameGrid from "../components/portal/GameGrid.vue"; import ContentStatePanel from "../components/portal/ContentStatePanel.vue";
const route = useRoute(); const router = useRouter(); const category = ref<CategoryItem | null>(null); const games = ref<PublishedGameSummary[]>([]); const loading = ref(true); const error = ref(""); const favorites = ref<string[]>(readFavorites().values); const slug = computed(() => String(route.params.slug));
async function load(): Promise<void> { loading.value = true; error.value = ""; try { const categories = await getCategories(); category.value = categories.find((item) => item.slug === slug.value) ?? null; if (!category.value) return; games.value = (await getCategoryGames(slug.value)).data; document.title = `${category.value.name}游戏｜星屿游廊`; } catch { error.value = "分类内容暂时无法加载。"; } finally { loading.value = false; } } function favorite(slug: string): void { favorites.value = toggleFavorite(slug).values; } function play(slug: string): void { rememberRecent(slug); void router.push(`/zh/game/${slug}/play`); } watch(slug, () => void load()); onMounted(() => void load());
</script><template><div class="portal-page"><section v-if="category" class="portal-page-heading"><span class="portal-eyebrow">CATEGORY / {{ category.slug }}</span><h1>{{ category.name }}</h1><p>{{ category.description }}</p></section><ContentStatePanel v-if="loading" kind="loading" title="正在打开分类" message="正在寻找可玩的作品。" /><ContentStatePanel v-else-if="!category" kind="empty" title="分类不存在" message="这个分类可能已经调整，请回到游戏大厅。" action="返回大厅" @action="router.push('/zh/games')" /><ContentStatePanel v-else-if="error" kind="error" title="分类加载失败" :message="error" action="重试" @action="load" /><ContentStatePanel v-else-if="!games.length" kind="empty" title="正在上新" message="这个分类暂时没有已发布游戏，过段时间再来看看吧。" /><GameGrid v-else :games="games" :favorites="favorites" @favorite="favorite" @play="play" /></div></template>
